MESSAGES = {}
for row in ROWS.strip().splitlines():
    if not row.strip():
        continue
    cells = row.split('|')
    if len(cells) != len(LANGS) + 1:
        raise ValueError('Invalid installer translation row: ' + cells[0])
    MESSAGES[cells[0]] = dict(zip(LANGS, cells[1:]))
